def getResults(queries):
    M = max(q[1] for q in queries)
    obs = sorted({q[1] for q in queries if q[0] == 1} | {0})  # 0 is a sentinel obstacle (origin)
    present = set(obs)

    # Fenwick tree for prefix maximum; values only ever increase
    tree = [0] * (M + 1)

    def upd(i, v):
        while i <= M:
            if tree[i] < v:
                tree[i] = v
            i += i & -i

    def qry(i):
        r = 0
        while i > 0:
            if tree[i] > r:
                r = tree[i]
            i -= i & -i
        return r

    # linked list of obstacles and initial gaps
    prv, nxt = {}, {}
    for a, b in zip(obs, obs[1:]):
        prv[b] = a
        nxt[a] = b
        upd(b, b - a)

    # union-find: find(p) = largest present obstacle <= p
    parent = [p if p in present else p - 1 for p in range(M + 1)]

    def find(p):
        root = p
        while parent[root] != root:
            root = parent[root]
        while parent[p] != root:
            parent[p], p = root, parent[p]
        return root

    ans = []
    for q in reversed(queries):
        if q[0] == 1:
            x = q[1]
            p = prv[x]
            n = nxt.get(x)
            parent[x] = x - 1          # obstacle x disappears
            if n is None:
                nxt.pop(p, None)
            else:
                nxt[p] = n
                prv[n] = p
                upd(n, n - p)          # merged gap, only grows
        else:
            x, sz = q[1], q[2]
            pred = find(x)
            ans.append(max(qry(pred), x - pred) >= sz)
    ans.reverse()
    return ans
